--
-- TOC entry 279 (class 1259 OID 24867)
-- Name: forecastreport_view; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.forecastreport_view AS
 SELECT DISTINCT COALESCE(forecast.name, ((((((forecastplan.item_id)::text || ' @ '::text) || (forecastplan.location_id)::text) || ' @ '::text) || (forecastplan.customer_id)::text))::character varying) AS name,
    forecastplan.item_id,
    forecastplan.location_id,
    forecastplan.customer_id
   FROM (public.forecastplan
     LEFT JOIN public.forecast ON ((((forecast.item_id)::text = (forecastplan.item_id)::text) AND ((forecast.location_id)::text = (forecastplan.location_id)::text) AND ((forecast.customer_id)::text = (forecastplan.customer_id)::text))))
  WITH NO DATA;


